import uuid
from datetime import datetime

from sqlalchemy import JSON, DateTime, ForeignKey, Integer, String, Text
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column

from app.db import Base


class BlueprintDraft(Base):
    """A versioned, source-grounded Blueprint draft generated by Life from the Founder's own
    indexed project materials.

    Founder Alpha item 8/9: the AI-generated `body` is ALWAYS a DRAFT pending explicit Founder
    approval (`status` starts 'draft', only a separate Founder action moves it to 'approved').
    It is traceable to its sources (`source_document_ids` / `source_refs` point at the immutable
    original Documents the retrieval used) and clearly separated from the originals — this row
    stores an AI INTERPRETATION only; it never holds or mutates original bytes. Each
    regeneration for the same `title` is a new `version` (immutable history). RLS-protected by
    `owner_id` exactly like document_chunks / knowledge_versions (see app/rls.py)."""

    __tablename__ = "blueprint_drafts"

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
    owner_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), ForeignKey("users.id", ondelete="CASCADE"), index=True)
    title: Mapped[str] = mapped_column(String(300), index=True)
    version: Mapped[int] = mapped_column(Integer)
    status: Mapped[str] = mapped_column(String(16), default="draft")  # draft | approved
    body: Mapped[str] = mapped_column(Text)
    generated_from_query: Mapped[str | None] = mapped_column(Text, nullable=True)
    source_document_ids: Mapped[list | None] = mapped_column(JSON, default=list)
    source_refs: Mapped[list | None] = mapped_column(JSON, default=list)
    model_provider: Mapped[str | None] = mapped_column(String(64), nullable=True)
    model_name: Mapped[str | None] = mapped_column(String(128), nullable=True)
    provenance: Mapped[dict | None] = mapped_column(JSON, default=dict)
    created_at: Mapped[datetime] = mapped_column(DateTime, default=datetime.utcnow)
    approved_at: Mapped[datetime | None] = mapped_column(DateTime, nullable=True)
    approved_by: Mapped[str | None] = mapped_column(String(128), nullable=True)
